// page-pending-walk.mjs — the staff frame while a page is on its way (D-149),
// and the server work it no longer repeats, against pnpm dev.
//
//   (cd packages/db && node --conditions=react-server --env-file=../../.env ../../plan/page-pending-walk.mjs [base])
//
// A throwaway STAFF member of villa logs in; a headless Chrome holds the
// cookie. On Dashboard, the walk clicks Bookings in the sidebar and looks
// at the page in the SAME tick: the title must already read "Bookings", the
// body must be the bones, and the sidebar must still be there (the frame
// stayed; only the content column changed). Then the real page arrives and
// the bones are gone. Then the two 404s that a Next loading boundary would
// have turned into 200s (why this is not one): a per_room page on a
// whole-resort tenant, and an unknown tenant. Deletes everything it made,
// its audit rows too (R-54).


const BASE = process.argv[2] ?? 'http://localhost:3000';
const SLUG = 'villa';
const OUT = join(dirname(fileURLToPath(import.meta.url)), 'page-pending', 'walk');
const RUN_START = new Date().toISOString();
let failures = 0;
const check = (ok, label, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? `  — ${detail}` : ''}`);
  if (!ok) failures++;
};

const { data: tenant } = await supabase.from('tenants').select('id').eq('slug', SLUG).single();
if (!tenant) throw new Error(`no tenant ${SLUG}`);
let userId;
let browser;
try {
  // A STAFF member of villa: the lowest role, which has Dashboard and Bookings.
  const email = `page-pending-walk-${Date.now()}@example.com`;
  const password = randomBytes(18).toString('base64url');
  const { data: user, error: userError } = await supabase.auth.admin.createUser({ email, password, email_confirm: true });
=== free-guests-walk
// free-guests-walk.mjs — D-147 (plan/free-guests.md), the walk: 7 checks on
// villa, HTTP and browser, against pnpm dev.
//
//   (cd packages/db && node --conditions=react-server --env-file=../../.env ../../plan/free-guests-walk.mjs)
//
//   1. The platform route, on a throwaway tenant with its DPA signed:
//      free_up_to_age 18 is refused by the trigger in words; 3 is accepted
//      and read back on the tenant's record. (Villa's own config cannot go
//      through that route: its DPA is unsigned and the gate fires on the
//      upsert, so the walk sets villa's rule on the service client.)
//   2. The staff setup route carries freeUpToAge 3; the public quote with
//      1 free child prices exactly like the quote without, and every line
//      carries free 1 / 0.
//   3. The booking page at 375 draws the second field, "Children aged 3 and
//      below" (plan/free-guests/book-375.png).
//   4. A staff stay with 4 guests + 1 free child: the list carries 4 and 1,
//      the total is the quote's; the stay page (S-15) at 375 says
//      "4 guests + 1 child (free)" (plan/free-guests/stay-375.png), and so
//      does the staff list row.
//   5. The web door: a request with 2 guests + 2 free children; Manage
//      booking's lookup returns free 2 on the room line.
//   6. The chatbot's tool: the result carries the rule while villa has one.
//   7. Restored: the config back as it was; the tool result has no rule;
//      the setup route says null.
//
// Villa's bookings config is changed on the service client and put back
// EXACTLY as it was in finally; the throwaway tenant is deleted; the two stays, the throwaway member,
// the throwaway super user and their audit rows on villa are removed. Nothing
// reaches OpenAI: executeTool() runs the tool, never the model.

const BASE = process.argv[2] ?? 'http://localhost:3000';
const OUT = join(dirname(fileURLToPath(import.meta.url)), 'free-guests');
mkdirSync(OUT, { recursive: true });
=== welcome-text-walk
// welcome-text-walk.mjs — the welcome line per tenant (D-139), against
// pnpm dev: the platform route takes it, the chat shows it, and the audit
// log keeps it.
//
//   (cd packages/db && node --conditions=react-server --env-file=../../.env ../../plan/welcome-text-walk.mjs)
//
// On a THROWAWAY tenant and a THROWAWAY super user (both removed at the end
// by the ids this run made, never by a name: trap 26). The tenant gets ONE
// documents row on service_role (no chunks: nothing is embedded), because an
// EMPTY knowledge base swaps the welcome line for "I am still being set up"
// (chat-screen.tsx, emptyKb), which the first run of this walk found. The
// welcome's text is read in a browser at 375, the routes over HTTP:
//   1. the chat opens with the DEFAULT line (lib/welcome-text.ts);
//   2. PATCH refuses an empty line and a 201-character one (400, the form's
//      words), takes a line (200, the detail carries it, trimmed),
//      tenant_public() gives it to anon, and the chat opens with it,
//      photographed into plan/welcome-text/;
//   3. the audit log has the super user's row with the column's name and
//      the before and after;
//   4. PATCH null clears it and the chat is back to the default.
// Nothing reaches OpenAI: the browser only loads the page.


const BASE = process.argv[2] ?? 'http://localhost:3000';
const OUT = join(dirname(fileURLToPath(import.meta.url)), 'welcome-text');
mkdirSync(OUT, { recursive: true });
const DEFAULT = 'Discover more about our resort, accommodations, amenities, and booking options.';
const LINE = 'Ask about our cabins, the lake and how to book a weekend.';

let failures = 0;
const check = (ok, what, detail = '') => {
  failures += ok ? 0 : 1;
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${what}${detail ? `  — ${detail}` : ''}`);
};
=== nav-layout-walk
// nav-layout-walk.mjs — the staff navigation after plan/nav-layout.md, in a
// real browser against pnpm dev: the sidebar's four sections by role, the top
// bar on every width (breadcrumb, bell, account menu), the account menu by
// keyboard and pointer, the phone drawer, and Log out from the menu.
// Replaces ui-refresh-phase2-walk.mjs's sidebar checks (its footer is gone).
//
//   (cd packages/db && node --conditions=react-server --env-file=../../.env ../../plan/nav-layout-walk.mjs [base-url])
//
// Two throwaway users (an OWNER of harbor, a STAFF member of villa), deleted
// at the end.


const BASE = process.argv[2] ?? 'http://localhost:3000';
let failures = 0;
const check = (ok, label, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${detail ? `  — ${detail}` : ''}`);
  if (!ok) failures++;
};

const { data: tenants } = await supabase.from('tenants').select('id, slug').in('slug', ['villa', 'harbor']);
const idOf = Object.fromEntries(tenants.map((t) => [t.slug, t.id]));
const stamp = Date.now();
const users = {};
async function makeUser(name, slug, role) {
  const email = `nav-walk-${name}-${stamp}@example.com`;
  const password = randomBytes(18).toString('base64url');
  const { data, error } = await supabase.auth.admin.createUser({ email, password, email_confirm: true });
  if (error) throw new Error(`create ${name}: ${error.message}`);
  users[name] = { id: data.user.id, email, password };
  const { error: e } = await supabase.from('memberships').insert({ user_id: data.user.id, tenant_id: idOf[slug], role });
  if (e) throw new Error(`membership ${name}: ${e.message}`);
}
async function cookieFor(slug, user) {
  const r = await fetch(`${BASE}/api/t/${slug}/admin/session`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: user.email, password: user.password }) });
  const c = (r.headers.getSetCookie?.() ?? []).find((x) => x.startsWith('rag_admin='))?.split(';')[0];
  if (!c) throw new Error(`login ${slug}: ${r.status}`);
  return c.slice('rag_admin='.length);
