const { supabase } = await import('./dist/service.js');
const { data: ts } = await supabase.from('tenants').select('id, slug').in('slug',['villa','alteza']);
for (const t of ts) {
  const u = await supabase.from('units').select('*').eq('tenant_id', t.id).limit(3);
  const s = await supabase.from('slots').select('*').eq('tenant_id', t.id).limit(5);
  const p = await supabase.from('push_subscriptions').select('id', { count: 'exact', head: true }).eq('tenant_id', t.id);
  const a = await supabase.from('tenant_applications').select('application_key, config').eq('tenant_id', t.id);
  console.log(t.slug, t.id, 'units', JSON.stringify(u.data?.map(x=>({id:x.id,name:x.name,active:x.active}))), 'slots', JSON.stringify(s.data?.map(x=>({id:x.id,name:x.name,active:x.active, keys:Object.keys(x).join('|')}))), 'push', p.count, JSON.stringify(a.data));
}" --input-type=module

